css:
.omd [data-omd-part="composer"],
.omd [data-omd-part="dialog"],
.omd [data-omd-part="menu"] {
  background-color: var(--omd-surface);
  background-image: var(--omd-glass-sheen);
  background-repeat: no-repeat;
  background-size: 100% 100%;
  -webkit-backdrop-filter: blur(26px) saturate(180%);
  backdrop-filter: blur(26px) saturate(180%);
}

.omd [data-omd-part="composer"] {
  border: 1px solid var(--omd-glass-rim);
  border-radius: var(--omd-radius-composer);
  box-shadow: inset 0 1px 0 var(--omd-glass-highlight), var(--omd-glass-shadow);
}

.omd [data-omd-part="composer"]:focus-within {
  border-color: var(--omd-focus);
  outline: 3px solid var(--omd-tint-accent);
  outline-offset: 0;
  box-shadow: inset 0 1px 0 var(--omd-glass-highlight), var(--omd-glass-shadow);
}


.omd [data-omd-part="input"] {
  background-color: transparent;
  border: 0;
  color: var(--omd-text);
  caret-color: var(--omd-accent);
  font-family: var(--omd-font-body);
}

.omd [data-omd-part="dialog"],
.omd [data-omd-part="menu"] {
  border: 1px solid var(--omd-glass-rim);
  border-radius: var(--omd-radius-panel);
  box-shadow: inset 0 1px 0 var(--omd-glass-highlight), var(--omd-glass-shadow-strong);
  color: var(--omd-text);
}

.omd [data-omd-part="menu"] { border-radius: var(--omd-radius-control); }



.omd [data-omd-part="sidebar"],
.omd [data-omd-part="header"],
.omd [data-omd-part="workbench"] {
  background-image: var(--omd-glass-sheen);
  background-repeat: no-repeat;
  background-size: 100% 100%;
  -webkit-backdrop-filter: blur(26px) saturate(180%);
  backdrop-filter: blur(26px) saturate(180%);
}


.omd [data-omd-part="sidebar"] {
  background-color: var(--omd-sidebar);
  box-shadow: inset -1px 0 0 var(--omd-glass-hairline);
}

.omd [data-omd-part="header"] {
  background-color: var(--omd-surface);
  box-shadow: inset 0 -1px 0 var(--omd-glass-hairline);
}


.omd [data-omd-part="workbench"] {
  background-color: var(--omd-surface);
  box-shadow: inset 0 1px 0 var(--omd-glass-hairline);
}

@media (min-width: 1200px) {
  .omd [data-omd-part="workbench"] { box-shadow: inset 1px 0 0 var(--omd-glass-hairline); }
}




.omd [data-omd-part="settings"],
.omd [data-omd-part="settings-shell"],
.omd [data-omd-part="settings-content"] {
  background-color: var(--omd-surface-solid);
  background-image: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  color: var(--omd-text);
  font-family: var(--omd-font-body);
}

.omd [data-omd-part="settings"] {
  border-radius: var(--omd-radius-panel);
}

.omd [data-omd-part="settings-shell"] {
  border-radius: var(--omd-radius-panel);
  box-shadow: inset 0 1px 0 var(--omd-glass-highlight), var(--omd-glass-shadow-strong);
}


.omd [data-omd-part="settings-nav"] {
  background-color: var(--omd-sidebar);
  background-image: none;
  color: var(--omd-text);
  font-family: var(--omd-font-ui);
}

.omd [data-omd-part="settings-nav-item"] {
  border: 0;
  border-radius: var(--omd-radius-control);
  background-color: transparent;
  color: var(--omd-muted);
}


.omd [data-omd-part="settings-nav-item"]:hover {
  background-color: var(--omd-hover);
}


.omd [data-omd-part="settings-nav-item"][data-omd-state="selected"] {
  background-color: var(--omd-selected);
  color: var(--omd-text);
  font-weight: 600;
}

.omd [data-omd-part="settings-nav-item"][data-omd-state="disabled"] {
  color: var(--omd-muted);
}


.omd [data-omd-part="settings-row"] {
  border-bottom: 1px solid var(--omd-separator);
  color: var(--omd-text);
}



.omd [data-omd-part="settings-tabs"] { border-bottom: 1px solid var(--omd-separator); }

.omd [data-omd-part="tab"] {
  border: 0;
  border-radius: 0;
  background-color: transparent;
  color: var(--omd-muted);
  font-weight: 500;
  letter-spacing: .002em;
}

.omd [data-omd-part="tab"]:hover { color: var(--omd-text); }
.omd [data-omd-part="tab"][data-omd-state="selected"] {
  color: var(--omd-accent-ink);
  font-weight: 600;
}



.omd [data-omd-part="segments"] {
  background-color: var(--omd-segment-track);
  border: 0;
  border-radius: var(--omd-radius-control);
}

.omd [data-omd-part="segment"] {
  border: 1px solid transparent;
  border-radius: 7px;
  background-color: transparent;
  color: var(--omd-text);
  font-weight: 500;
}


.omd [data-omd-part="segment"]:hover { background-color: var(--omd-tint-accent); }
.omd [data-omd-part="segment"][data-omd-state="selected"] {
  background-color: var(--omd-segment-thumb);
  color: var(--omd-text);
  font-weight: 600;
}


.omd [data-omd-part="segment"][data-omd-state="disabled"] { color: var(--omd-muted); }


.omd [data-omd-part="savebar"] {
  background-color: var(--omd-surface-solid);
  border-top: 1px solid var(--omd-separator);
  color: var(--omd-muted);
}




.omd [data-omd-part="form-control"],
.omd [data-omd-part="field-input"],
.omd [data-omd-part="select"] {
  background-color: var(--omd-field-bg);
  border: 1px solid var(--omd-field-border);
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
  font-family: var(--omd-font-body);
  caret-color: var(--omd-accent);
}

.omd [data-omd-part="form-control"]:focus-visible,
.omd [data-omd-part="field-input"]:focus-visible,
.omd [data-omd-part="select"]:focus-visible {
  border-color: var(--omd-focus);
  outline: 2px solid var(--omd-focus);
  outline-offset: 1px;
}

.omd [data-omd-part="form-control"][data-omd-state="disabled"],
.omd [data-omd-part="field-input"][data-omd-state="disabled"],
.omd [data-omd-part="select"][data-omd-state="disabled"] {
  color: var(--omd-muted);
  border-color: var(--omd-separator);
}


.omd [data-omd-part="checkbox"] { accent-color: var(--omd-switch-on); }

.omd [data-omd-part="switch"] {
  border-radius: 999px;
  accent-color: var(--omd-switch-on);
}

.omd [data-omd-part="switch"][data-omd-state="checked"] { background-color: var(--omd-switch-on); }

.omd [data-omd-part="switch"][data-omd-state="disabled"] { accent-color: var(--omd-muted); }

.omd [data-omd-part="file-input"] {
  border-radius: var(--omd-radius-control);
  color: var(--omd-muted);
}




.omd [data-omd-part="button"] {
  border-radius: var(--omd-radius-control);
  font-family: var(--omd-font-ui);
  font-weight: 500;
  letter-spacing: .002em;
}

.omd [data-omd-part="button"]:focus-visible {
  outline: 2px solid var(--omd-focus);
  outline-offset: 2px;
}

.omd [data-omd-part="button"][data-omd-state="disabled"] { color: var(--omd-muted); }


.omd [data-omd-part="button-primary"] {
  background-color: var(--omd-button-bg);
  border: 0;
  border-radius: 999px;
  color: var(--omd-button-fg);
  font-weight: 600;
}

.omd [data-omd-part="button-primary"]:hover {
  background-color: var(--omd-button-hover);
}


.omd [data-omd-part="button-quiet"] {
  background-color: transparent;
  border: 0;
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
}

.omd [data-omd-part="button-quiet"]:hover { background-color: var(--omd-hover); }


.omd [data-omd-part="icon-button"] {
  background-color: transparent;
  border: 0;
  border-radius: var(--omd-radius-control);
  color: var(--omd-text);
}

.omd [data-omd-part="icon-button"]:hover { background-color: var(--omd-hover); }


.omd [data-omd-part="send"] {
  background-color: var(--omd-button-bg);
  border: 0;
  border-radius: 999px;
  color: var(--omd-button-fg);
}

.omd [data-omd-part="send"]:hover { background-color: var(--omd-button-hover); }

.omd [data-omd-part="send"][data-omd-state="disabled"] {
  background-color: var(--omd-hover);
  color: var(--omd-muted);
}

.omd [data-omd-part="button-primary"][data-omd-state="disabled"] {
  background-color: var(--omd-hover);
  color: var(--omd-muted);
}

.omd [data-omd-part="button-quiet"][data-omd-state="disabled"],
.omd [data-omd-part="icon-button"][data-omd-state="disabled"] {
  background-color: transparent;
  color: var(--omd-muted);
}



.omd [data-omd-part="conversation"] {
  background-color: var(--omd-bg);
  color: var(--omd-text);
  font-family: var(--omd-font-body);
  letter-spacing: .002em;
}


.omd [data-omd-part="message-user"] {
  background-color: var(--omd-user-bg);
  border: 1px solid var(--omd-message-border);
  border-radius: 20px 20px 6px 20px;
  color: var(--omd-text);
}


.omd [data-omd-part="sidebar-row"] {
  border: 0;
  border-radius: 12px;
  background-color: transparent;
  color: var(--omd-text);
}

.omd [data-omd-part="sidebar-row"]:hover { background-color: var(--omd-hover); }
.omd [data-omd-part="sidebar-row"][data-omd-state="selected"] {
  background-color: var(--omd-selected);
  color: var(--omd-accent-ink);
  font-weight: 600;
}



.omd [data-omd-part="process-toggle"] {
  background-color: transparent;
  border: 0;
  color: var(--omd-muted);
  font-weight: 500;
}

.omd [data-omd-part="process-toggle"]:hover { color: var(--omd-text); }


.omd [data-omd-part="tool-group"] {
  background-color: var(--omd-card-bg);
  border: 1px solid var(--omd-card-border);
  border-radius: var(--omd-radius-panel);
  color: var(--omd-text);
}

.omd [data-omd-part="tool-row"] {
  background-color: transparent;
  border-top: 1px solid var(--omd-separator);
  color: var(--omd-text);
}


.omd [data-omd-part="code-block"],
.omd [data-omd-part="code"] {
  background-color: var(--omd-code-bg);
  border: 1px solid var(--omd-card-border);
  border-radius: 12px;
  color: var(--omd-text);
  font-family: var(--omd-font-mono);
  font-variant-numeric: tabular-nums;
}


.omd [data-omd-part="code-inline"] {
  background-color: var(--omd-code-bg);
  border: 0;
  border-radius: 6px;
  color: var(--omd-text);
  font-family: var(--omd-font-mono);
}


.omd [data-omd-part="statusbar"] {
  background-color: transparent;
  border: 0;
  color: var(--omd-muted);
  font-variant-numeric: tabular-nums;
}



@media (prefers-reduced-transparency: reduce) {
  .omd [data-omd-part="sidebar"],
  .omd [data-omd-part="header"],
  .omd [data-omd-part="workbench"],
  .omd [data-omd-part="composer"],
  .omd [data-omd-part="dialog"],
  .omd [data-omd-part="menu"] {
    background-color: var(--omd-surface-solid);
    background-image: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .omd [data-omd-part="sidebar"] { background-color: var(--omd-sidebar-solid); }
}

@media (prefers-contrast: more) {
  .omd [data-omd-part="sidebar"],
  .omd [data-omd-part="header"],
  .omd [data-omd-part="workbench"],
  .omd [data-omd-part="composer"],
  .omd [data-omd-part="dialog"],
  .omd [data-omd-part="menu"],
  .omd [data-omd-part="tool-group"],
  .omd [data-omd-part="code-block"] {
    background-image: none;
    border-color: var(--omd-border);
  }

  .omd [data-omd-part="tool-group"],
  .omd [data-omd-part="code-block"] { background-color: var(--omd-surface-solid); }
}
